const progress=document.createElement('div');progress.className='scroll-progress';document.body.append(progress);
const motion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.12});
document.querySelectorAll('main section, .invite, .event, .dress>div, .footer, .art-banner, .art-caption').forEach(el=>{el.classList.add('reveal');observer.observe(el)});
let scheduled=false;addEventListener('scroll',()=>{if(!scheduled){requestAnimationFrame(()=>{let max=document.documentElement.scrollHeight-innerHeight;progress.style.width=(max?scrollY/max*100:0)+'%';scheduled=false});scheduled=true}},{passive:true});
const gate=document.getElementById('gate');
gate.innerHTML=`<div class="envelope-stage"><div class="envelope-intro"><div class="eyebrow">A little envelope. A lifetime of love.</div><p>With the blessings of Radha & Krishna</p></div><div class="envelope"><div class="envelope-back"></div><div class="envelope-card"><svg class="feather" aria-hidden="true"><use href="#feather"/></svg><div class="card-blessing">राधे कृष्ण</div><div class="card-names">Aarav <i>&</i> Meera</div><div class="eyebrow">Joyfully invite you · 18 February 2027</div></div><div class="envelope-pocket"></div><div class="envelope-front"></div><div class="envelope-flap"></div><div class="envelope-label">A CELEBRATION OF LOVE</div><button class="seal" id="envelope-seal" aria-label="Click here to open the wedding invitation">Click here</button></div><p class="envelope-hint">An invitation, sealed with love.</p><div class="opening-status" role="status" aria-live="polite"></div></div><button class="skip-envelope" id="skip-envelope">Skip opening →</button>`;
let opening=false;const finishOpening=()=>{gate.classList.add('open');gate.inert=true;document.body.style.overflow='';const hero=document.querySelector('h1');hero.tabIndex=-1;hero.focus({preventScroll:true})};
document.body.style.overflow='hidden';
document.getElementById('envelope-seal').onclick=()=>{if(opening)return;opening=true;gate.querySelector('.opening-status').textContent='Opening your invitation…';if(motion){finishOpening();return}gate.classList.add('unsealing');setTimeout(()=>gate.classList.add('card-rising'),650);setTimeout(()=>gate.classList.add('finale'),2250);setTimeout(finishOpening,3050)};
document.getElementById('skip-envelope').onclick=finishOpening;
// Ivory paper, gold wax, and small jasmine branches inspired by the supplied reference.
