const env=document.querySelector('.envelope');env.insertAdjacentHTML('beforeend',flowerBranch.replace('class="botanical"','class="botanical top"')+flowerBranch.replace('class="botanical"','class="botanical bottom"')+'<svg class="envelope-arrow" viewBox="0 0 50 70" aria-hidden="true"><path d="M3 65C48 64 48 30 27 9M27 9L29 25M27 9L43 14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>');
document.querySelector('.seal').textContent='D N';document.querySelector('.envelope-hint').textContent='Click to open envelope';document.querySelector('.card-names').innerHTML='Dhiraj <i>&</i> Neha';document.querySelector('.envelope-card .eyebrow').textContent='A beautiful beginning, together';document.querySelector('.envelope-intro .eyebrow').textContent='An invitation, sealed with love';
env.insertAdjacentHTML('beforeend','<img class="jasmine-real top" src="jasmine-real.svg" alt="" aria-hidden="true"><img class="jasmine-real bottom" src="jasmine-real.svg" alt="" aria-hidden="true">');
const clusterImages=Array.from({length:5},()=>'<img src="jasmine-real.svg" alt="">').join('');env.insertAdjacentHTML('beforeend','<div class="flower-corner top" aria-hidden="true">'+clusterImages+'</div><div class="flower-corner bottom" aria-hidden="true">'+clusterImages+'</div>');
document.querySelectorAll('.flower-corner,.jasmine-real,.botanical').forEach(el=>el.remove());env.insertAdjacentHTML('beforeend','<img class="whole-floral top" src="jasmine-corner.svg" alt="" aria-hidden="true"><img class="whole-floral bottom" src="jasmine-corner.svg" alt="" aria-hidden="true">');
const waxButton=document.querySelector('.seal');waxButton.innerHTML='<img src="dn-wax-seal.svg" alt="Dhiraj and Neha intertwined monogram wax seal" draggable="false">';
